// Lookup helper: K("K2") → source object
window.K = (id) => (window.SRCS.find(s => s.k === id) || { k: id, cite: "source pending", date: "n.d.", cat: "kimi", fact: "" });

// Drill-down source string used by every chart: "K2 · USACE ERDC (2026)"
window.KSTR = (ids) => (ids || []).map(id => { const s = window.K(id); return `${s.k} · ${s.cite.split(",")[0].split("(")[0].trim()} (${s.date})`; }).join(" · ");

// Drill-down source LINKS (HTML): each anchor becomes a clickable link to the original
// source opening in a new tab — "K2 · USACE ERDC technical report ↗". Anchors with no
// external source render as plain text explicitly flagged "derived analysis (no external source)".
window.KLINK = (ids) => (ids || []).map(id => {
  const s = window.K(id);
  const label = s.cite.split(",")[0].split("(")[0].trim();
  if (s.url) return `<a class="src-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.k} · ${label} ↗</a>`;
  return `<span class="src-derived">${s.k} · ${label} (${s.date}) — derived analysis (no external source)</span>`;
}).join(" · ");

// Linkify bare K-tokens inside prose source strings (chart footers, modal source basis):
// "… program bulletins · dates as published (K116–K132)" → each K# becomes a link.
window.KLINKIFY = (text) => String(text == null ? "" : text).replace(/\bK(\d{1,3})\b/g, (m, n) => {
  const s = window.SRCS.find(x => x.k === "K" + n);
  if (s && s.url) return `<a class="src-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${m} ↗</a>`;
  return m;
});

// Single-anchor variant used by the K-register footer and grant rows.
window.KA = (id) => {
  const s = window.K(id);
  if (!s.url) return null;
  return `<a class="src-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.k} ↗</a>`;
};
